using System;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEngine.EventSystems;using System.Linq;using System.Collections.Generic;
public static class CheckGameUI {
 public static async Task<string> Start(){var g=UnityEngine.Object.FindAnyObjectByType<ForgeMvp>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(ForgeMvp).GetField("progressLoaded",flags).SetValue(g,false);typeof(ForgeMvp).GetField("showTitle",flags).SetValue(g,false);typeof(ForgeMvp).GetMethod("StopMouseTrace",flags).Invoke(g,null);typeof(ForgeMvp).GetMethod("ResetProgressForDebug",flags).Invoke(g,new object[]{false});Application.runInBackground=true;await Task.Delay(400);g.HierarchyGame.Refresh();return "Game UI active: "+g.HierarchyGame.gameObject.activeInHierarchy+" windows="+g.HierarchyGame.codes.Count;}
 public static async Task<string> Run(){await Start();var g=UnityEngine.Object.FindAnyObjectByType<ForgeMvp>();var ui=g.HierarchyGame;var checks=new List<string>();void Assert(bool value,string name){if(!value)throw new Exception(name);checks.Add("PASS "+name);}void Click(string name){ui.Node(name).GetComponent<Button>().onClick.Invoke();}
 Click("AddCode");Assert(ui.codes.Count==2,"add code prefab");var view=ui.codes.Values.Last();view.title.text="test_module";view.title.onEndEdit.Invoke(view.title.text);view.editor.text="Material = 1\nBlade = 1(Material)\n2(Blade, 7)\n3(Blade)\n4(Blade, 0)\n5(Blade, 1)\n!Blade";
 view.collapse.onClick.Invoke();Assert(!view.body.gameObject.activeSelf,"collapse");view.collapse.onClick.Invoke();Assert(view.body.gameObject.activeSelf,"expand");
 var handle=view.GetComponentsInChildren<ForgeUIDrag>().First(d=>!d.resize);var e=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left,position=new Vector2(250,350)};var before=view.rect.anchoredPosition;handle.OnBeginDrag(e);e.position+=new Vector2(50,20);handle.OnDrag(e);handle.OnEndDrag(e);Assert(view.rect.anchoredPosition!=before,"window drag");await Task.Delay(50);var after=view.rect.anchoredPosition;ui.Refresh();Assert(view.rect.anchoredPosition==after,"drag persists after refresh");
 int caret=view.editor.caretPosition;view.editor.OnScroll(new PointerEventData(EventSystem.current){scrollDelta=new Vector2(0,-6)});Assert(caret==view.editor.caretPosition,"wheel does not move caret");
 view.run.onClick.Invoke();for(int i=0;i<200&&g.HierarchyBusy;i++)await Task.Delay(100);Assert(!g.HierarchyBusy,"craft execution completes");ui.Refresh();await Task.Delay(100);Assert(ui.salesList.childCount>0&&ui.salesList.childCount==((ForgeShop)typeof(ForgeMvp).GetField("shop",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(g)).Count,"crafted items appear in sale prefabs");ui.salesList.GetChild(0).GetComponent<Button>().onClick.Invoke();int gold=g.HierarchyGold;Click("Sell");Assert(g.HierarchyGold>gold,"sale button commits gold");
 Click("GuideToggle");Assert(ui.Node("Guide").gameObject.activeInHierarchy,"guide opens");g.GameGuideAction("guide-section:테크 트리");g.GameGuideAction("guide-section:게임 소개");Assert(!ui.Node("GuideSection1").gameObject.activeSelf,"locked research section hidden");
 typeof(ForgeMvp).GetField("gold",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(g,100000);g.HierarchyBuy(ForgeTechnology.Offers.First(o=>o.Id==ForgeTechnology.AutomationRoot),1);ui.Refresh();Assert(g.HierarchyGuideHasNew,"purchase adds unread guide notice");Assert(ui.Node("GuideSection1").gameObject.activeSelf,"research section unlocked");
 Click("TechToggle");await Task.Delay(200);Assert(g.HierarchyTree.gameObject.activeInHierarchy&&!ui.gameObject.activeInHierarchy,"tree transition");g.CloseHierarchyTree();await Task.Delay(200);Assert(ui.gameObject.activeInHierarchy,"return from tree");
 Click("ProgressToggle");Assert(ui.Node("Progress").gameObject.activeSelf,"workshop records");Click("ProgressBack");Click("MenuToggle");Assert(ui.Node("Menu").gameObject.activeSelf,"menu");Click("Resume");
 view.close.onClick.Invoke();Assert(ui.Node("Delete").gameObject.activeSelf,"delete confirmation");Click("CancelDelete");Assert(ui.codes.Count==2,"delete cancelled");view.close.onClick.Invoke();Click("ConfirmDelete");Assert(ui.codes.Count==1,"confirmed code removal");
 Click("ProgressToggle");Click("TutorialOpen");await Task.Delay(3000);Click("TutorialStart");await Task.Delay(500);Click("TutorialMaterial1");var input=ui.Node("TutorialInput").GetComponent<InputField>();input.text="Material = 1";Click("TutorialSubmit");await Task.Delay(200);Assert(((ForgeTutorialLesson)typeof(ForgeMvp).GetField("lesson",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(g)).Stage==2,"tutorial input and submit");Click("TutorialClose");await Task.Delay(200);Assert(ui.Node("Play").gameObject.activeSelf,"tutorial return");
 var result=string.Join("\n",checks);System.IO.File.WriteAllText("Docs/Performance/InGameUI/functional-checks.txt",result);return result;}
 static void Queue(ForgeCodeInput field,Event e){typeof(Event).GetMethod("QueueEvent",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Invoke(null,new object[]{e});field.OnUpdateSelected(new BaseEventData(EventSystem.current));}
 public static async Task<string> InputCheck(){var g=UnityEngine.Object.FindAnyObjectByType<ForgeMvp>();var view=g.HierarchyGame.codes.Values.First();var field=view.editor;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();field.text="if True:";field.ActivateInputField();await Task.Delay(100);field.caretPosition=field.text.Length;await Task.Delay(100);Queue(field,new Event{type=EventType.KeyDown,keyCode=KeyCode.Return,character='\n'});await Task.Delay(150);if(!field.text.EndsWith("\n    "))throw new Exception("newline indentation: "+field.text);EditorGUIUtility.QueueGameViewInputEvent(new Event{type=EventType.KeyDown,keyCode=KeyCode.Tab});await Task.Delay(100);EditorGUIUtility.QueueGameViewInputEvent(new Event{type=EventType.KeyDown,keyCode=KeyCode.Z,modifiers=EventModifiers.Control});await Task.Delay(100);if(!field.text.EndsWith("\n    "))throw new Exception("undo indentation");field.text=string.Join("\n",Enumerable.Repeat("Material = 1",100));field.caretPosition=0;await Task.Delay(100);int caret=field.caretPosition;field.OnScroll(new PointerEventData(EventSystem.current){scrollDelta=new Vector2(0,-6)});await Task.Delay(100);if(field.caretPosition!=caret||field.outerScroll.content.anchoredPosition.y<=0)throw new Exception("code wheel scroll");field.text="";return "PASS Unity event queue (not physical keyboard): newline indentation, Tab, Ctrl+Z, long-code wheel scrolling without caret movement";}
 public static async Task<string> Extras(){var g=UnityEngine.Object.FindAnyObjectByType<ForgeMvp>();var ui=g.HierarchyGame;var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(ForgeMvp).GetField("showGuideBook",flags).SetValue(g,true);g.HierarchyTechnology.Restore(Array.Empty<BlueprintFeature>(),ForgeTechnology.Offers.Where(o=>o.Kind!=ForgePurchaseKind.Material).Select(o=>o.Id).ToArray());var smiths=(ForgeBlacksmiths)typeof(ForgeMvp).GetField("blacksmiths",flags).GetValue(g);smiths.hireTier=5;smiths.favorUnlocked=smiths.positionUnlocked=smiths.demandUnlocked=true;ui.Refresh();await Task.Delay(100);int count=0;foreach(bool english in new[]{false,true}){g.SetEnglishGuideUnlocked(english);for(int i=0;i<BlueprintGuide.Entries.Count;i++){g.GameGuideAction("guide-entry:"+i);Canvas.ForceUpdateCanvases();var body=ui.Node("GuideBody").GetComponent<Text>();if(body.preferredHeight>body.rectTransform.rect.height+2)throw new Exception("Guide body clipped: "+i);count++;}}
 var guide=ui.Node("Guide").GetComponent<ForgeUIWindow>();var old=guide.rect.sizeDelta;guide.rect.sizeDelta=guide.resize.GetComponent<ForgeUIDrag>().minimum;Canvas.ForceUpdateCanvases();if(ui.Node("GuideBody").GetComponent<Text>().preferredHeight>ui.Node("GuideBody").GetComponent<RectTransform>().rect.height+2)throw new Exception("Guide minimum-size text");guide.fold.onClick.Invoke();if(guide.body.activeSelf)throw new Exception("Guide fold");guide.fold.onClick.Invoke();if(!guide.body.activeSelf)throw new Exception("Guide unfold");guide.rect.sizeDelta=old;
 var view=ui.codes.Values.First();var size=view.rect.sizeDelta;view.rect.sizeDelta=new Vector2(340,200);await Task.Delay(50);Canvas.ForceUpdateCanvases();if(view.editor.textComponent.rectTransform.rect.height<24)throw new Exception("Minimum code viewport");view.rect.sizeDelta=size;view.editor.text="Blade = ";view.run.onClick.Invoke();ui.Refresh();if(!view.status.text.Contains("오류"))throw new Exception("Compile error display");view.status.GetComponent<Button>().onClick.Invoke();await Task.Delay(100);view.editor.text="";
 var hover=ui.Node("MaterialTile1").GetComponent<ForgeUIHover>();hover.OnPointerEnter(new PointerEventData(EventSystem.current){position=new Vector2(400,300)});if(!ui.codeHelp.gameObject.activeSelf)throw new Exception("Material tooltip");hover.OnPointerExit(new PointerEventData(EventSystem.current));ui.HideCodeHelp();
 int objects=ui.GetComponentsInChildren<Transform>(true).Length;await Task.Delay(1200);if(ui.GetComponentsInChildren<Transform>(true).Length!=objects)throw new Exception("UI objects created while idle");g.SetEnglishGuideUnlocked(false);g.GameGuideAction("guide-section:게임 소개");string result="PASS "+count+" numeric/English guide pages; minimum guide/code dimensions; fold/unfold; error display/reveal; material tooltip; no idle UI object creation";System.IO.File.WriteAllText("Docs/Performance/InGameUI/extra-checks.txt",result);return result;}
}
